// Cleanup old tracker entries every 5 minutes
function cleanCorruptionTracker() {
  const now = Date.now();
  for (const [key, entry] of _corruptionTracker) {
    if (now - entry.last_seen > 300000) { // 5 min stale
      _corruptionTracker.delete(key);
    }
  }
}

// ═══════════════════════════════════════════════════════════════
// v47.0: GLOBAL SETTINGS SYSTEM
// Key-value store in SQLite with safe defaults.
// ═══════════════════════════════════════════════════════════════

function getSetting(key, defaultValue = null) {
  try {
    const row = initSqliteDb().prepare('SELECT value FROM settings WHERE key = ?').get(key);
    return row ? row.value : defaultValue;
  } catch { return defaultValue; }
}

function setSetting(key, value) {
  try {
    initSqliteDb().prepare('INSERT OR REPLACE INTO settings (key, value) VALUES (?, ?)').run(key, String(value));
    return true;
  } catch (e) { log('[Settings] Failed to set ' + key + ': ' + e.message, 'warn'); return false; }
}

function getAllSettings() {
  try {
    const rows = initSqliteDb().prepare('SELECT key, value FROM settings').all();
    const result = {};
    for (const r of rows) result[r.key] = r.value;
    return result;
  } catch { return {}; }
}

function isFeatureEnabled(key) {
  return getSetting(key, 'false') === 'true';
}

function getSystemMode() {
  return getSetting('system_mode', 'safe');
}

// ═══════════════════════════════════════════════════════════════
// v62.0: ADDON SYSTEM
// Bootstrap with the legacy loader first, then switch to the active addon
// runtime loader once the writable addons directory has been resolved.
// This prevents packaged desktop builds from hard-failing when bundled
// addon files sit under an ESM parent path.
