  try { const tp = _f('transferProtection'); if (tp) { tp.cleanTransferSnapshots(); tp.decayPlayerRisk(); } } catch {}
  try { const te = _f('tribeEnforcer'); if (te) { te.cleanTribeEvents(); te.syncTribeSizeFromConfig(); } } catch {}
