// v45.1: Startup recovery — mark running items as failed
function recoverQueueOnStartup() {
  try {
    const db = initSqliteDb();
    const stuck = db.prepare(`SELECT * FROM command_queue WHERE status = 'running'`).all();
    if (stuck.length > 0) {
      db.prepare(`UPDATE command_queue SET status = 'failed', updated_at = datetime('now') WHERE status = 'running'`).run();
      log(`[BOOT] Marked ${stuck.length} stuck queue items as failed (agent restarted)`, 'warn');
      emitAgentEvent('system:recovered_state', `Recovered ${stuck.length} stuck tasks after restart`, { level: 'warning' });
    }
    dbClearCompletedQueue();
  } catch (e) { log('[BOOT] Queue recovery error: ' + e.message, 'warn'); }
}

// v45.1: Command dedup — returns existing task_id if duplicate found
function findDuplicateTaskId(commandType, serverId) {
  if (!serverId) return null;
  // Check in-memory queue
  const inQueue = _commandQueue.find(q => q.commandType === commandType && q.serverId === serverId);
  if (inQueue) return inQueue.task_id;
  // Check active command locks
  if (_activeCommandLock && _activeCommandLock.has(serverId)) {
    const lock = _activeCommandLock.get(serverId);
    if (lock && lock.command_type === commandType) return lock.command_id || null;
  }
  return null;
}

function enqueueHeavyCommand(fn, description, opts = {}) {
  return new Promise((resolve, reject) => {
    const commandType = opts.commandType || 'unknown';
    const serverId = opts.serverId || null;

    // Circuit breaker check
    if (!checkCircuitBreaker(commandType)) {
      emitAgentEvent('system:degraded', `Command rejected (circuit breaker open): ${description}`, { level: 'error' });
      return reject(new Error('System degraded — only stop commands accepted. Try again shortly.'));
    }

    // Queue size check
    if (_commandQueue.length >= MAX_QUEUE_SIZE) {
      emitAgentEvent('system:backpressure', `Queue full (${MAX_QUEUE_SIZE}) — rejecting: ${description}`, { level: 'error' });
      return reject(new Error('Command queue full — try again later'));
    }

    // v45.1: Dedup — return existing task instead of rejecting
    const existingTaskId = findDuplicateTaskId(commandType, serverId);
    if (existingTaskId) {
      log(`[CommandQueue] Duplicate found: ${commandType} for ${serverId} → returning existing task ${existingTaskId}`, 'info');
      return resolve({ duplicate: true, task_id: existingTaskId, message: `${commandType} already in progress` });
    }

    const priority = opts.priority || getCommandPriority(commandType);
    const retryRules = getRetryRules(commandType);

    const task = createBackgroundTask(commandType, description, {
      serverName: opts.serverName,
      clusterName: opts.clusterName,
    });
    updateBackgroundTask(task.id, { status: 'queued', message: `Queued (position ${_commandQueue.length + 1})` });

    if (!canAcceptNewTask()) {
      emitAgentEvent('system:backpressure', `Queued: ${description} (active=${_activeCommandCount}, priority=${priority})`, { level: 'warning' });
    }

    const item = {
      fn, resolve, reject, description, priority, task_id: task.id,
      queued_at: Date.now(), commandType, serverId,
      retries: 0, maxRetries: retryRules.retry ? retryRules.maxRetries : 0,
      serverName: opts.serverName,
    };

    _commandQueue.push(item);
    dbPersistQueueItem(item); // Persist to SQLite

    sortQueue();
    drainCommandQueue();
  });
}

async function drainCommandQueue() {
  sortQueue();

  while (_activeCommandCount < MAX_CONCURRENT_COMMANDS && _commandQueue.length > 0) {
    const item = _commandQueue.shift();
    _activeCommandCount++;

    // Persist status change
    dbUpdateQueueStatus(item.task_id, 'running');
    updateBackgroundTask(item.task_id, { status: 'running', message: `Executing: ${item.description}`, progress: 10 });

    // v45.1: Per-command timeout
    const timeoutRules = getTimeoutRules(item.commandType);
    let timedOut = false;
    const abortController = { cancelled: false };
    const timer = setTimeout(() => {
      timedOut = true;
      abortController.cancelled = true;
      log(`[CommandQueue] Timeout on: ${item.description} — cancelling`, 'error');
      emitAgentEvent('system:command_timeout', `Command timed out: ${item.description}`, { level: 'error', serverName: item.serverName });

      if (timeoutRules.failOnTimeout) {
        updateBackgroundTask(item.task_id, { status: 'failed', error: 'Command timed out', message: 'Timed out' });
        dbUpdateQueueStatus(item.task_id, 'failed');
        item.reject(new Error('Command timed out'));
      } else {
        // Mark as unknown — allow manual retry
        updateBackgroundTask(item.task_id, { status: 'failed', error: 'Timed out (may still be running)', message: 'Timeout — check manually' });
        dbUpdateQueueStatus(item.task_id, 'failed');
        item.resolve({ status: 'unknown', message: 'Command timed out but may still be running' });
      }

      circuitBreakerFailure();
      _activeCommandCount--;
      if (_commandQueue.length > 0) setImmediate(drainCommandQueue);
    }, timeoutRules.timeoutMs);

    try {
      const result = await item.fn(abortController);
      clearTimeout(timer);
      if (!timedOut) {
        updateBackgroundTask(item.task_id, { status: 'completed', progress: 100, message: 'Completed' });
        dbUpdateQueueStatus(item.task_id, 'completed');
        circuitBreakerSuccess();
        item.resolve(result);
      }
    } catch (e) {
      clearTimeout(timer);
      if (!timedOut) {
        circuitBreakerFailure();
        if (item.retries < item.maxRetries) {
          item.retries++;
          const backoffMs = Math.min(1000 * Math.pow(2, item.retries), 30000);
          log(`[CommandQueue] Retry ${item.retries}/${item.maxRetries} for: ${item.description} (backoff ${backoffMs}ms)`, 'warn');
          emitAgentEvent('system:retry', `Retrying ${item.description} (attempt ${item.retries + 1})`, {
            level: 'warning', serverName: item.serverName,
          });
          updateBackgroundTask(item.task_id, {
            status: 'queued',
            message: `Retry ${item.retries}/${item.maxRetries} in ${Math.round(backoffMs / 1000)}s`,
            progress: 0,
          });
          dbUpdateQueueStatus(item.task_id, 'queued');

          setTimeout(() => {
            _commandQueue.push(item);
            sortQueue();
            drainCommandQueue();
          }, backoffMs);
        } else {
          updateBackgroundTask(item.task_id, { status: 'failed', error: e.message, message: `Failed: ${e.message}` });
          dbUpdateQueueStatus(item.task_id, 'failed');
          item.reject(e);
        }
      }
    } finally {
      if (!timedOut) {
        _activeCommandCount--;
        if (_commandQueue.length > 0) setImmediate(drainCommandQueue);
      }
    }
  }
}

// ═══════════════════════════════════════════════════════════════
// v43.0: RATE LIMITING — prevent command spam per server
// ═══════════════════════════════════════════════════════════════
const _serverCommandCooldown = new Map(); // server_id → last_command_timestamp
const COMMAND_COOLDOWN_MS = 2000;

function isRateLimited(serverId) {
  const last = _serverCommandCooldown.get(serverId);
  if (!last) return false;
  return (Date.now() - last) < COMMAND_COOLDOWN_MS;
}

function recordCommandTime(serverId) {
  _serverCommandCooldown.set(serverId, Date.now());
}

