// v43.0: SAFE EXECUTE — global error guard wrapper
// ═══════════════════════════════════════════════════════════════
function safeExecute(fn, context) {
  try {
    return fn();
  } catch (e) {
    log(`[SAFE ERROR] ${context}: ${e.message}`, 'error');
    emitAgentEvent('system:error', `${context}: ${e.message}`, { level: 'error' });
    return undefined;
  }
}

async function safeExecuteAsync(fn, context) {
  try {
    return await fn();
  } catch (e) {
    log(`[SAFE ERROR] ${context}: ${e.message}`, 'error');
    emitAgentEvent('system:error', `${context}: ${e.message}`, { level: 'error' });
    return undefined;
  }
}
