// -- Per-Server Command Queue (v28.0) -------------------------
// Prevents duplicate/overlapping commands per server
const serverCommandQueue = new Map(); // server_id -> { active: boolean, queue: [] }

function getServerQueue(serverId) {
  if (!serverCommandQueue.has(serverId)) {
    serverCommandQueue.set(serverId, { active: false, queue: [] });
  }
  return serverCommandQueue.get(serverId);
}

async function enqueueServerCommand(serverId, fn) {
  const q = getServerQueue(serverId);
  return new Promise((resolve, reject) => {
    q.queue.push({ fn, resolve, reject });
    processServerQueue(serverId);
  });
}

async function processServerQueue(serverId) {
  const q = getServerQueue(serverId);
  if (q.active || q.queue.length === 0) return;
  q.active = true;
  const { fn, resolve, reject } = q.queue.shift();
  try {
    const result = await fn();
    resolve(result);
  } catch (e) {
    reject(e);
  } finally {
    q.active = false;
    if (q.queue.length > 0) processServerQueue(serverId);
  }
}

