function dbGetClusterServers(clusterId) {
  try {
    // Servers whose install_dir starts with the cluster's full_path
    const cluster = dbGetCluster(clusterId);
    if (!cluster) return [];
    const prefix = cluster.full_path.replace(/\\/g, '/').toLowerCase();
    return initSqliteDb().prepare('SELECT * FROM servers').all().filter(s => {
      if (!s.install_dir) return false;
      return s.install_dir.replace(/\\/g, '/').toLowerCase().startsWith(prefix);
    });
  } catch { return []; }
}

// ─── Agent Event Buffer ───
const MAX_AGENT_EVENTS = 200;

function emitAgentEvent(type, message, opts = {}) {
  const level = opts.level || 'info';
  const logLevel = level === 'error' ? 'error' : level === 'warning' ? 'warn' : level === 'success' ? 'success' : 'info';
  log(`[Event] ${type}: ${message}`, logLevel);
  try {
    const db = initSqliteDb();
    db.prepare(
      `INSERT INTO agent_events (type, message, level, path, server_name, cluster_name, error_message)
       VALUES (?, ?, ?, ?, ?, ?, ?)`
    ).run(type, message, level, opts.path || null, opts.serverName || null, opts.clusterName || null, opts.error || null);
    // Trim old events
    const count = db.prepare('SELECT COUNT(*) as cnt FROM agent_events').get();
    if (count && count.cnt > MAX_AGENT_EVENTS) {
      db.prepare(`DELETE FROM agent_events WHERE id IN (SELECT id FROM agent_events ORDER BY id ASC LIMIT ?)`).run(count.cnt - MAX_AGENT_EVENTS);
    }
  } catch { /* non-critical */ }

  // v62.0: Forward to Discord alerts feature (if loaded)
  try {
    const discord = _f('discordAlerts');
    if (discord && typeof discord.enqueueAlert === 'function') {
      discord.enqueueAlert(type, message, opts);
    }
  } catch { /* non-critical */ }
}

function dbGetRecentEvents(limit = 50) {
  try {
    return initSqliteDb().prepare('SELECT * FROM agent_events ORDER BY id DESC LIMIT ?').all(limit);
  } catch { return []; }
}

