// ─── v41.0: Remote Relay State ───
function dbUpdateRelayState(status, extra = {}) {
  try {
    const db = initSqliteDb();
    const existing = db.prepare("SELECT * FROM remote_relay WHERE id = 'singleton'").get();
    if (existing) {
      const updates = [];
      const vals = [];
      updates.push('status = ?'); vals.push(status);
      updates.push("updated_at = datetime('now')");
      if (status === 'connected') { updates.push("last_connected_at = datetime('now')"); }
      if (extra.commands_relayed) { updates.push('commands_relayed = commands_relayed + 1'); }
      if (extra.last_command) { updates.push("last_command_at = datetime('now')"); }
      db.prepare(`UPDATE remote_relay SET ${updates.join(', ')} WHERE id = 'singleton'`).run(...vals);
    } else {
      db.prepare("INSERT INTO remote_relay (id, status) VALUES ('singleton', ?)").run(status);
    }
  } catch (e) { log('[DB] Failed to update relay state: ' + e.message, 'warn'); }
}

function dbGetRelayState() {
  try {
    return initSqliteDb().prepare("SELECT * FROM remote_relay WHERE id = 'singleton'").get() || { status: 'disconnected' };
  } catch { return { status: 'disconnected' }; }
}

// ─── Cluster Filesystem Operations ───
function sanitizeFolderName(name) {
  return String(name || '').replace(/[^a-zA-Z0-9_\-\s.]/g, '').trim().replace(/\s+/g, '_');
}

function normalizePath(p) {
  return path.resolve(String(p || '').replace(/\//g, path.sep).replace(/\\+$/g, ''));
}

function isPathSafe(targetPath) {
  // Prevent path traversal
  const resolved = path.resolve(targetPath);
  if (resolved.includes('..')) return false;
  // Prevent system-critical paths
  const lower = resolved.toLowerCase();
  const blocked = ['c:\\windows', 'c:\\program files', 'c:\\users', '/usr', '/etc', '/var', '/bin', '/sbin'];
  return !blocked.some(b => lower.startsWith(b));
}

function createClusterDirectory(clusterName, basePath) {
  emitAgentEvent('cluster:create:start', `Creating cluster "${clusterName}"...`, { clusterName, path: basePath });

  // Validate
  const safeName = sanitizeFolderName(clusterName);
  if (!safeName) {
    const err = 'Invalid cluster name after sanitization';
    emitAgentEvent('cluster:create:error', err, { level: 'error', clusterName });
    throw new Error(err);
  }

  const normalizedBase = normalizePath(basePath);
  if (!isPathSafe(normalizedBase)) {
    const err = `Unsafe base path: ${normalizedBase}`;
    emitAgentEvent('cluster:create:error', err, { level: 'error', clusterName, path: normalizedBase });
    throw new Error(err);
  }

  // Ensure base path exists (auto-create for local-first flow)
  if (!fs.existsSync(normalizedBase)) {
    try {
      fs.mkdirSync(normalizedBase, { recursive: true });
      log(`[Cluster] Auto-created base path: ${normalizedBase}`, 'info');
    } catch (mkErr) {
      const err = `Failed to create base path: ${mkErr.message}`;
      emitAgentEvent('cluster:create:error', err, { level: 'error', clusterName, path: normalizedBase });
      throw new Error(err);
    }
  }

  const clusterPath = path.join(normalizedBase, safeName);

  // Check if already exists
  if (fs.existsSync(clusterPath)) {
    log(`[Cluster] Cluster directory already exists: ${clusterPath}`, 'warn');
    emitAgentEvent('cluster:create:success', `Cluster "${clusterName}" already exists at ${clusterPath}`, { level: 'warning', clusterName, path: clusterPath });
    return { full_path: clusterPath, existed: true };
  }

  // Create cluster directory
  try {
    fs.mkdirSync(clusterPath, { recursive: true });
  } catch (e) {
    const err = `Failed to create cluster directory: ${e.message}`;
    emitAgentEvent('cluster:create:error', err, { level: 'error', clusterName, path: clusterPath, error: e.message });
    throw new Error(err);
  }

  // Create required ARK cluster subdirectory
  const arkClusterDir = path.join(clusterPath, 'ShooterGame', 'Saved', 'clusters');
  try {
    fs.mkdirSync(arkClusterDir, { recursive: true });
  } catch (e) {
    log(`[Cluster] Warning: failed to create ARK cluster subdir: ${e.message}`, 'warn');
  }

  emitAgentEvent('cluster:create:success', `Cluster "${clusterName}" created at ${clusterPath}`, { level: 'success', clusterName, path: clusterPath });
  return { full_path: clusterPath, existed: false };
}

async function deleteClusterDirectory(clusterRecord, servers) {
  const clusterName = clusterRecord.name;
  const clusterPath = clusterRecord.full_path;
  emitAgentEvent('cluster:delete:start', `Deleting cluster "${clusterName}"...`, { clusterName, path: clusterPath });

  // Safety: validate path
  if (!clusterPath || !isPathSafe(clusterPath)) {
    const err = `Unsafe or missing cluster path: ${clusterPath}`;
    emitAgentEvent('cluster:delete:error', err, { level: 'error', clusterName });
    throw new Error(err);
  }

  // Validate path is within known base
  const normalizedCluster = path.resolve(clusterPath).toLowerCase();
  if (!isPathAllowed(clusterPath)) {
    const err = `Cluster path outside approved directories: ${clusterPath}`;
    emitAgentEvent('cluster:delete:error', err, { level: 'error', clusterName, path: clusterPath });
    throw new Error(err);
  }

  // Check for running servers in this cluster
  const clusterServers = (servers || []).filter(s => {
    if (!s.install_dir) return false;
    return path.resolve(s.install_dir).toLowerCase().startsWith(normalizedCluster + path.sep.toLowerCase());
  });

  const runningServers = clusterServers.filter(s => isServerRunning(s));
  if (runningServers.length > 0) {
    log(`[Cluster] Stopping ${runningServers.length} running server(s) before cluster deletion...`, 'warn');
    for (const rs of runningServers) {
      emitAgentEvent('server:stop', `Stopping ${rs.name} for cluster deletion`, { level: 'warning', serverName: rs.name, clusterName });
      stopServer(rs);
    }
    // Wait for servers to stop (non-blocking)
    for (let i = 0; i < 30; i++) {
      const stillRunning = clusterServers.filter(s => isServerRunning(s));
      if (stillRunning.length === 0) break;
      await new Promise(resolve => setTimeout(resolve, 1000));
    }
  }

  // Delete the directory
  if (!fs.existsSync(clusterPath)) {
    emitAgentEvent('cluster:delete:success', `Cluster directory already removed: ${clusterPath}`, { level: 'warning', clusterName, path: clusterPath });
    return { deleted: true, existed: false };
  }

  let retries = 0;
  const maxRetries = 2;
  while (retries < maxRetries) {
    try {
      await fs.promises.rm(clusterPath, { recursive: true, force: true });
      emitAgentEvent('cluster:delete:success', `Cluster "${clusterName}" deleted successfully`, { level: 'success', clusterName, path: clusterPath });

      // Remove associated servers from agent config (immutable filter)
      const removedIds = new Set(clusterServers.map(cs => cs.server_id));
      const newServers = servers.filter(s => !removedIds.has(s.server_id));
      servers.length = 0;
      servers.push(...newServers);
      for (const cs of clusterServers) {
        dbCascadeDeleteServer(cs.server_id || cs.id);
        emitAgentEvent('server:delete:success', `Server "${cs.name}" removed (cluster deleted)`, { level: 'info', serverName: cs.name, clusterName });
      }

      return { deleted: true, existed: true, serversRemoved: clusterServers.length };
    } catch (e) {
      retries++;
      log(`[Cluster] Delete attempt ${retries}/${maxRetries} failed: ${e.message}`, 'error');
      if (retries >= maxRetries) {
        const err = `Failed to delete cluster directory after ${maxRetries} attempts: ${e.message}`;
        emitAgentEvent('cluster:delete:error', err, { level: 'error', clusterName, path: clusterPath, error: e.message });
        throw new Error(err);
      }
    }
  }
}

function resolveServerDirFromCluster(clusterId, serverName) {
  const cluster = dbGetCluster(clusterId);
  if (!cluster) return null;
  const safeName = sanitizeFolderName(serverName);
  if (!safeName) return null;
  return path.join(cluster.full_path, safeName);
}

