// -- Safe route wrapper: catches all errors in API handlers --
function safeRoute(handler) {
  return async function(req, res, url, cfg, servers) {
    try {
      return await handler(req, res, url, cfg, servers);
    } catch (e) {
      log('[API] Unhandled error in route: ' + e.message, 'error');
      try {
        res.writeHead(500, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Internal server error', message: e.message }));
      } catch (_) {}
    }
  };
}

// -- Input validation helpers --
function validateServerId(body, res, apiJsonFn) {
  if (!body || !body.server_id || typeof body.server_id !== 'string' || body.server_id.trim().length === 0) {
    apiJsonFn(res, { success: false, error: 'server_id is required and must be a non-empty string' }, 400);
    return false;
  }
  return true;
}

