// Safe JSON body parser — returns null on failure instead of empty object
function parseBodySafe(req) {
  return new Promise((resolve) => {
    let body = '';
    let destroyed = false;
    req.on('data', (c) => {
      body += c;
      if (body.length > 1e6) { destroyed = true; req.destroy(); resolve(null); }
    });
    req.on('end', () => {
      if (destroyed) return;
      if (!body || !body.trim()) { resolve(null); return; }
      try {
        const parsed = JSON.parse(body);
        if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
          resolve(null);
          return;
        }
        resolve(parsed);
      } catch (_) {
        resolve(null);
      }
    });
    req.on('error', () => resolve(null));
  });
}

// Validate POST body exists and is a valid object
function validateRequestBody(body, res, apiJsonFn) {
  if (!body || typeof body !== 'object') {
    apiJsonFn(res, { success: false, error: 'Invalid request body — expected JSON object' }, 400);
    return false;
  }
  return true;
}

// Sanitize payload — remove undefined/null values, ensure object
function sanitizePayload(payload) {
  if (!payload || typeof payload !== 'object') return {};
  const clean = {};
  for (const [key, value] of Object.entries(payload)) {
    if (value === undefined || value === null) continue;
    clean[key] = value;
  }
  return clean;
}

// Validate port is a valid number
function validatePort(value, fieldName) {
  if (value === undefined || value === null) return null; // optional
  const num = Number(value);
  if (!Number.isFinite(num) || num < 1 || num > 65535 || num !== Math.floor(num)) {
    return `${fieldName} must be a valid port number (1-65535)`;
  }
  return null;
}

// Per-server command rate limiter (lightweight — in-memory)
const _commandRateMap = new Map(); // server_id → last_command_ts
const RATE_LIMIT_MS = 500;

function isCommandRateLimited(serverId) {
  if (!serverId) return false;
  const last = _commandRateMap.get(serverId);
  const now = Date.now();
  if (last && (now - last) < RATE_LIMIT_MS) return true;
  return false;
}

function recordCommandRateTime(serverId) {
  if (serverId) _commandRateMap.set(serverId, Date.now());
  // Clean up old entries periodically
  if (_commandRateMap.size > 200) {
    const cutoff = Date.now() - 60000;
    for (const [k, v] of _commandRateMap) {
      if (v < cutoff) _commandRateMap.delete(k);
    }
  }
}

// Log API errors to SQLite for observability
function logApiError(endpoint, payload, errorMessage) {
  try {
    const db = initSqliteDb();
    const sanitized = payload ? JSON.stringify(payload).slice(0, 500) : '{}';
    db.prepare(
      'INSERT INTO api_error_log (endpoint, payload, error_message) VALUES (?, ?, ?)'
    ).run(endpoint, sanitized, (errorMessage || '').slice(0, 1000));
  } catch (_) {
    // Silently fail — this is a logging helper, not critical path
  }
}

// Ensure api_error_log table exists
function ensureApiErrorLogTable() {
  try {
    const db = initSqliteDb();
    db.exec(`
      CREATE TABLE IF NOT EXISTS api_error_log (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        endpoint TEXT NOT NULL,
        payload TEXT,
        error_message TEXT NOT NULL,
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP
      )
    `);
    // Auto-cleanup: keep last 500 entries
    db.exec(`DELETE FROM api_error_log WHERE id NOT IN (SELECT id FROM api_error_log ORDER BY created_at DESC LIMIT 500)`);
  } catch (_) {}
}


// -- Duplicate start prevention --
function isServerProcessAlive(srv) {
  const sid = srv.server_id || srv.id || srv.name;
  const pid = spawnedPids.get(sid) || spawnedPids.get(srv.name);
  if (!pid) return false;
  try {
    process.kill(pid, 0);
    return true;
  } catch { return false; }
}

// -- Timeout wrapper for long operations --
function withTimeout(promise, ms, label) {
  return Promise.race([
    promise,
    new Promise(function(_, reject) {
      setTimeout(function() { reject(new Error('Timeout after ' + ms + 'ms: ' + (label || 'operation'))); }, ms);
    }),
  ]);
}

// -- Mod pipeline lock --
const _modProcessingLock = new Map(); // server_id → true

function acquireModLock(serverId) {
  if (_modProcessingLock.get(serverId)) return false;
  _modProcessingLock.set(serverId, true);
  return true;
}

function releaseModLock(serverId) {
  _modProcessingLock.delete(serverId);
}

// -- API key security (optional) --
function checkApiKey(req, cfg, res, apiJsonFn) {
  if (ELECTRON_MANAGED) return true;
  const configuredKey = cfg && cfg.api_key;
  if (!configuredKey) return true; // no key configured = open
  const providedKey = req.headers['x-api-key'];
  if (providedKey === configuredKey) return true;
  apiJsonFn(res, { error: 'Unauthorized — invalid or missing x-api-key header' }, 401);
  return false;
}

// -- Server state helpers --
function dbUpsertServerState(serverId, data) {
  try {
    const db = initSqliteDb();
    db.prepare(`INSERT INTO server_state (server_id, status, pid, players, cpu, ram, updated_at)
      VALUES (?, ?, ?, ?, ?, ?, datetime('now'))
      ON CONFLICT(server_id) DO UPDATE SET
        status = excluded.status, pid = excluded.pid, players = excluded.players,
        cpu = excluded.cpu, ram = excluded.ram, updated_at = datetime('now')
    `).run(
      serverId,
      data.status || 'unknown',
      data.pid || null,
      data.players || 0,
      data.cpu || 0,
      data.ram || 0
    );
  } catch (e) { log('[STATE] Failed to upsert server state: ' + e.message, 'warn'); }
}

function dbGetAllServerState() {
  try {
    const db = initSqliteDb();
    return db.prepare('SELECT * FROM server_state').all();
  } catch (e) { log('[STATE] Failed to fetch server state: ' + e.message, 'warn'); return []; }
}

// v24.3: Resource path tracking - persistent storage for all managed resources
function dbTrackResource(id, type, name, resourcePath, meta) {
  try {
    const db = initSqliteDb();
    db.prepare(`INSERT OR REPLACE INTO resource_paths (id, type, name, path, meta, updated_at)
      VALUES (?, ?, ?, ?, ?, datetime('now'))`).run(id, type, name, resourcePath, meta ? JSON.stringify(meta) : null);
    log(`[ResourceTracker] Tracked ${type} "${name}" at ${resourcePath}`, 'success');
  } catch (e) { log('[ResourceTracker] Failed to track resource: ' + e.message, 'warn'); }
}

function dbGetResourcePath(id) {
  try {
    const db = initSqliteDb();
    const row = db.prepare('SELECT * FROM resource_paths WHERE id = ?').get(id);
    return row || null;
  } catch (e) { log('[ResourceTracker] Failed to get resource: ' + e.message, 'warn'); return null; }
}

function dbGetResourcesByType(type) {
  try {
    const db = initSqliteDb();
    return db.prepare('SELECT * FROM resource_paths WHERE type = ? ORDER BY created_at DESC').all(type);
  } catch (e) { log('[ResourceTracker] Failed to get resources: ' + e.message, 'warn'); return []; }
}

function dbGetAllResources() {
  try {
    const db = initSqliteDb();
    return db.prepare('SELECT * FROM resource_paths ORDER BY type, created_at DESC').all();
  } catch (e) { log('[ResourceTracker] Failed to get all resources: ' + e.message, 'warn'); return []; }
}

function dbRemoveResource(id) {
  try {
    const db = initSqliteDb();
    const result = db.prepare('DELETE FROM resource_paths WHERE id = ?').run(id);
    if (result.changes > 0) log(`[ResourceTracker] Removed resource ${id}`, 'success');
    return result.changes > 0;
  } catch (e) { log('[ResourceTracker] Failed to remove resource: ' + e.message, 'warn'); return false; }
}

// v24.3: Validate path is within allowed directories
function isPathAllowed(targetPath) {
  if (!targetPath) return false;
  const normalized = path.resolve(targetPath).toLowerCase();
  const allowedRoots = [
    path.resolve(PATHS.servers).toLowerCase(),
    path.resolve(PATHS.backups).toLowerCase(),
    path.resolve(PATHS.cluster).toLowerCase(),
    path.resolve(PATHS.logs).toLowerCase(),
    path.resolve(PATHS.trash).toLowerCase(),
    path.resolve(PATHS.data).toLowerCase(),
  ];
  // Also allow custom paths from config
  try {
    const cfgPath = fs.existsSync(PATHS.configJson) ? PATHS.configJson : path.join(AGENT_DIR, 'config.json');
    if (fs.existsSync(cfgPath)) {
      const cfgData = JSON.parse(fs.readFileSync(cfgPath, 'utf8'));
      if (cfgData.paths) {
        for (const p of Object.values(cfgData.paths)) {
          if (typeof p === 'string') allowedRoots.push(path.resolve(p).toLowerCase());
        }
      }
      if (Array.isArray(cfgData.scan_paths)) {
        for (const sp of cfgData.scan_paths) {
          if (sp) allowedRoots.push(path.resolve(sp).toLowerCase());
        }
      }
    }
  } catch (_) {}
  // Allow common ARK directories on all drives
  const driveLetters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split('');
  for (const d of driveLetters) {
    allowedRoots.push(path.resolve(`${d}:\\ARKServers`).toLowerCase());
    allowedRoots.push(path.resolve(`${d}:\\ArkServers`).toLowerCase());
  }
  return allowedRoots.some(root => normalized.startsWith(root + path.sep) || normalized === root);
}

