// v24.2: Load user-configured paths from config.json and apply overrides
function loadCustomPaths() {
  const result = { ...DEFAULT_PATHS };
  try {
    const cfgPath = fs.existsSync(path.join(AGENT_DIR, 'config', 'config.json'))
      ? path.join(AGENT_DIR, 'config', 'config.json')
      : path.join(AGENT_DIR, 'config.json');
    if (fs.existsSync(cfgPath)) {
      const cfgData = JSON.parse(fs.readFileSync(cfgPath, 'utf8'));
      const customPaths = cfgData.paths || {};
      if (customPaths.servers && typeof customPaths.servers === 'string') result.servers = customPaths.servers;
      if (customPaths.backups && typeof customPaths.backups === 'string') result.backups = customPaths.backups;
      if (customPaths.clusters && typeof customPaths.clusters === 'string') result.cluster = customPaths.clusters;
      if (customPaths.logs && typeof customPaths.logs === 'string') {
        result.logs = customPaths.logs;
        result.logFile = path.join(customPaths.logs, 'trenches-agent.log');
      }
    }
  } catch (_) { /* use defaults */ }
  return result;
}

const PATHS = loadCustomPaths();

// v30.0: Cached drive + storage path info (refreshed every 60s to avoid wmic spam)
const _cachedDriveInfo = { data: [], lastUpdate: 0 };
const _cachedStoragePaths = { data: {}, lastUpdate: 0 };
const STORAGE_CACHE_MS = 60000;

function refreshStorageCache() {
  const now = Date.now();
  if (now - _cachedDriveInfo.lastUpdate >= STORAGE_CACHE_MS) {
    try {
      _cachedDriveInfo.data = detectDrives();
    } catch {
      _cachedDriveInfo.data = [];
    }
    _cachedDriveInfo.lastUpdate = now;
  }
  if (now - _cachedStoragePaths.lastUpdate >= STORAGE_CACHE_MS) {
    try {
      _cachedStoragePaths.data = getStoragePaths();
    } catch {
      _cachedStoragePaths.data = {};
    }
    _cachedStoragePaths.lastUpdate = now;
  }
}

// v24.2: Detect available drives on Windows
function detectDrives() {
  if (os.platform() !== 'win32') return [{ drive: '/', total_gb: 0, free_gb: 0, label: 'root' }];
  const drives = [];
  try {
    const { execSync } = require('child_process');
    const raw = execSync('wmic logicaldisk get DeviceID,FreeSpace,Size,VolumeName /format:csv', { encoding: 'utf8', timeout: 10000 });
    const lines = raw.trim().split('\n').filter(l => l.includes(','));
    for (let i = 1; i < lines.length; i++) {
      const cols = lines[i].trim().split(',');
      if (cols.length < 4) continue;
      const drive = (cols[1] || '').trim();
      const freeBytes = parseInt(cols[2] || '0', 10);
      const totalBytes = parseInt(cols[3] || '0', 10);
      const label = (cols[4] || '').trim();
      if (!drive || !totalBytes) continue;
      drives.push({
        drive: drive + '\\',
        label: label || drive,
        total_gb: +(totalBytes / 1073741824).toFixed(1),
        free_gb: +(freeBytes / 1073741824).toFixed(1),
      });
    }
  } catch (e) {
    // Fallback: just list C:\
    drives.push({ drive: 'C:\\', label: 'C:', total_gb: 0, free_gb: 0 });
  }
  return drives;
}

// v24.2: Get current storage paths (with defaults and custom)
function getStoragePaths() {
  const customPaths = {};
  try {
    const cfgPath = fs.existsSync(PATHS.configJson) ? PATHS.configJson : path.join(AGENT_DIR, 'config.json');
    if (fs.existsSync(cfgPath)) {
      const cfgData = JSON.parse(fs.readFileSync(cfgPath, 'utf8'));
      if (cfgData.paths) Object.assign(customPaths, cfgData.paths);
    }
  } catch (_) {}
  return {
    servers: { path: PATHS.servers, is_custom: !!customPaths.servers, default: DEFAULT_PATHS.servers },
    backups: { path: PATHS.backups, is_custom: !!customPaths.backups, default: DEFAULT_PATHS.backups },
    clusters: { path: PATHS.cluster, is_custom: !!customPaths.clusters, default: DEFAULT_PATHS.cluster },
    logs: { path: PATHS.logs, is_custom: !!customPaths.logs, default: DEFAULT_PATHS.logs },
  };
}

// v24.4: Save custom storage paths to config.json AND hot-reload PATHS at runtime
function saveStoragePaths(newPaths) {
  const cfgPath = fs.existsSync(PATHS.configJson) ? PATHS.configJson : path.join(AGENT_DIR, 'config', 'config.json');
  let cfgData = {};
  try { cfgData = JSON.parse(fs.readFileSync(cfgPath, 'utf8')); } catch (_) {}
  cfgData.paths = cfgData.paths || {};
  const validKeys = ['servers', 'backups', 'clusters', 'logs'];
  for (const key of validKeys) {
    if (newPaths[key] && typeof newPaths[key] === 'string') {
      cfgData.paths[key] = newPaths[key];
      // Create directory if it doesn't exist
      try { if (!fs.existsSync(newPaths[key])) fs.mkdirSync(newPaths[key], { recursive: true }); } catch (_) {}
    }
  }
  try { fs.writeFileSync(cfgPath, JSON.stringify(cfgData, null, 2), 'utf8'); } catch (_) {}

  // v24.4: Hot-reload — apply saved paths to the live PATHS object immediately
  applyCustomPaths();
  log('[Paths] Custom paths applied at runtime (no restart needed)', 'success');

  return cfgData.paths;
}

// v24.4: Apply custom paths from config.json to the live PATHS object
function applyCustomPaths() {
  try {
    const cfgPath = fs.existsSync(PATHS.configJson)
      ? PATHS.configJson
      : path.join(AGENT_DIR, 'config', 'config.json');
    if (!fs.existsSync(cfgPath)) return;
    const cfg = JSON.parse(fs.readFileSync(cfgPath, 'utf8'));
    if (cfg.paths) {
      if (cfg.paths.servers && typeof cfg.paths.servers === 'string') PATHS.servers = cfg.paths.servers;
      if (cfg.paths.backups && typeof cfg.paths.backups === 'string') PATHS.backups = cfg.paths.backups;
      if (cfg.paths.clusters && typeof cfg.paths.clusters === 'string') PATHS.cluster = cfg.paths.clusters;
      if (cfg.paths.logs && typeof cfg.paths.logs === 'string') {
        PATHS.logs = cfg.paths.logs;
        PATHS.logFile = path.join(cfg.paths.logs, 'trenches-agent.log');
      }
    }
  } catch (e) {
    log('[Paths] Failed to apply custom paths: ' + (e.message || e), 'warn');
  }
}

