          const masterRows = db.prepare("SELECT config_type, content FROM server_configs WHERE server_id = 'cluster'").all();
          if (masterRows.length === 0) throw new Error('No master config found');
          const stmt = db.prepare(`INSERT OR REPLACE INTO server_configs (server_id, config_type, content, updated_at) VALUES (?, ?, ?, datetime('now'))`);
          const txn = db.transaction(() => {
            for (const m of masterRows) {
              stmt.run(payload.server_id, m.config_type, m.content);
            }
          });
          txn();
          log(`[CMD] Config drift fixed for server ${payload.server_id} — ${masterRows.length} config(s) synced from master`, 'success');
          result = JSON.stringify({ success: true, data: { synced: masterRows.length } });
