        try {
          const db = initSqliteDb();
          const rows = db.prepare('SELECT * FROM server_health').all();
          const cooldownMs = parseInt(getSetting('restart_cooldown_ms', '30000'), 10);
          const enriched = rows.map(r => {
            const lastCrashTs = r.last_crash ? new Date(r.last_crash).getTime() : 0;
            const cooldownActive = lastCrashTs > 0 && (Date.now() - lastCrashTs) < cooldownMs;
            return { ...r, cooldown_active: cooldownActive, restart_disabled: !!r.restart_disabled };
          });
          result = JSON.stringify({ success: true, data: { servers: enriched } });
        } catch (e) { result = JSON.stringify({ success: false, error: e.message }); status = 'failed'; errorMsg = e.message; }
